  'src.sv': { en: `WKO: contributions 2026`, nl: `WKO: bijdragen 2026`, fr: `WKO : cotisations 2026` },
  'src.fb': { en: `BMF: Familienbonus Plus`, nl: `BMF: Familienbonus Plus`, fr: `BMF : Familienbonus Plus` },
  'src.kmb': { en: `oesterreich.gv.at: Kindermehrbetrag`, nl: `oesterreich.gv.at: Kindermehrbetrag`, fr: `oesterreich.gv.at : Kindermehrbetrag` },
  'src.stat': { en: `Statistik Austria: wage tax statistics 2024`, nl: `Statistik Austria: loonbelastingstatistiek 2024`, fr: `Statistik Austria : statistique de l'impôt sur les salaires 2024` },
